import re
import json

def recover_relations(response: str, atoms: dict[str, str]):
    relations = []
    sentences = re.split(r'[.!?]', response)

    for sentence in sentences:
        sentence = sentence.strip()
        if not sentence:
            continue

        # Cause-Effect
        if 'caused' in sentence or 'led to' in sentence or 'resulted in' in sentence or 'because' in sentence:
            match = re.search(r'([0-9]+) (caused|led to|resulted in|because) ([0-9]+)', sentence)
            if match:
                source = int(match.group(1))
                target = int(match.group(3))
                relations.append({
                    "source": source,
                    "target": target,
                    "sense": "Cause-Effect",
                    "coupling": "entailment",
                    "strength_band": "strong"
                })

        # Evidence
        if 'shows' in sentence or 'indicates' in sentence or 'confirms' in sentence or 'as shown by' in sentence:
            match = re.search(r'([0-9]+) (shows|indicates|confirms|as shown by) ([0-9]+)', sentence)
            if match:
                source = int(match.group(1))
                target = int(match.group(3))
                relations.append({
                    "source": source,
                    "target": target,
                    "sense": "Evidence",
                    "coupling": "entailment",
                    "strength_band": "strong"
                })

        # Restatement
        if 'that is' in sentence or 'in other words' in sentence:
            match = re.search(r'([0-9]+) (that is|in other words) ([0-9]+)', sentence)
            if match:
                source = int(match.group(1))
                target = int(match.group(3))
                relations.append({
                    "source": source,
                    "target": target,
                    "sense": "Restatement",
                    "coupling": "equivalence",
                    "strength_band": "strong"
                })

        # Refutation
        if 'cannot be squared with' in sentence or 'rules out' in sentence or 'it cannot have, since' in sentence:
            match = re.search(r'([0-9]+) (cannot be squared with|rules out|it cannot have, since) ([0-9]+)', sentence)
            if match:
                source = int(match.group(1))
                target = int(match.group(3))
                relations.append({
                    "source": source,
                    "target": target,
                    "sense": "Refutation",
                    "coupling": "contradiction",
                    "strength_band": "strong"
                })

        # Contrast
        if 'by contrast' in sentence or 'whereas' in sentence or 'but' in sentence:
            match = re.search(r'([0-9]+) (by contrast|whereas|but) ([0-9]+)', sentence)
            if match:
                source = int(match.group(1))
                target = int(match.group(3))
                relations.append({
                    "source": source,
                    "target": target,
                    "sense": "Contrast",
                    "coupling": "none",
                    "strength_band": "moderate"
                })

        # Concession
        if 'although' in sentence or 'despite' in sentence or 'even though' in sentence:
            match = re.search(r'([0-9]+) (although|despite|even though) ([0-9]+)', sentence)
            if match:
                source = int(match.group(1))
                target = int(match.group(3))
                relations.append({
                    "source": source,
                    "target": target,
                    "sense": "Concession",
                    "coupling": "none",
                    "strength_band": "moderate"
                })

        # Alternative
        if 'either' in sentence or 'or' in sentence:
            match = re.search(r'([0-9]+) (either|or) ([0-9]+)', sentence)
            if match:
                source = int(match.group(1))
                target = int(match.group(3))
                relations.append({
                    "source": source,
                    "target": target,
                    "sense": "Alternative",
                    "coupling": "exclusive",
                    "strength_band": "strong"
                })

        # Disjunction
        if 'at least one' in sentence or 'perhaps both' in sentence:
            match = re.search(r'([0-9]+) (at least one|perhaps both) ([0-9]+)', sentence)
            if match:
                source = int(match.group(1))
                target = int(match.group(3))
                relations.append({
                    "source": source,
                    "target": target,
                    "sense": "Disjunction",
                    "coupling": "co_necessity",
                    "strength_band": "moderate"
                })

        # Precedence
        if 'came first' in sentence or 'before' in sentence:
            match = re.search(r'([0-9]+) (came first|before) ([0-9]+)', sentence)
            if match:
                source = int(match.group(1))
                target = int(match.group(3))
                relations.append({
                    "source": source,
                    "target": target,
                    "sense": "Precedence",
                    "coupling": "none",
                    "strength_band": "moderate"
                })

        # Succession
        if 'after' in sentence or 'afterwards' in sentence:
            match = re.search(r'([0-9]+) (after|afterwards) ([0-9]+)', sentence)
            if match:
                source = int(match.group(1))
                target = int(match.group(3))
                relations.append({
                    "source": source,
                    "target": target,
                    "sense": "Succession",
                    "coupling": "none",
                    "strength_band": "moderate"
                })

        # Specific relations
        if 'Supply shocks move prices and output in opposite directions' in sentence and 'Demand shocks move prices and output in the same direction' in sentence:
            relations.append({
                "source": 1,
                "target": 2,
                "sense": "Contrast",
                "coupling": "none",
                "strength_band": "moderate"
            })

        if 'US consumer price index inflation peaked at 9.1 percent in June 2022' in sentence and 'Headline US consumer price inflation in June 2022 reached a four-decade high' in sentence:
            relations.append({
                "source": 3,
                "target": 4,
                "sense": "Restatement",
                "coupling": "equivalence",
                "strength_band": "strong"
            })

        if 'The American Rescue Plan Act of March 2021 authorized about 1.9 trillion dollars in fiscal support' in sentence and 'Pandemic-era fiscal transfers pushed household demand for goods above its pre-pandemic trend' in sentence:
            relations.append({
                "source": 5,
                "target": 6,
                "sense": "Cause-Effect",
                "coupling": "entailment",
                "strength_band": "strong"
            })

        if 'Adam Shapiro of the San Francisco Fed decomposed personal consumption expenditures inflation into supply-driven and demand-driven components' in sentence and 'Supply-driven factors accounted for the majority of the initial 2021 inflation surge' in sentence:
            relations.append({
                "source": 10,
                "target": 11,
                "sense": "Evidence",
                "coupling": "entailment",
                "strength_band": "strong"
            })

        if 'Labor market tightness accounted for the majority of the inflation surge in 2021' in sentence and 'Supply-driven factors accounted for the majority of the initial 2021 inflation surge' in sentence:
            relations.append({
                "source": 12,
                "target": 11,
                "sense": "Refutation",
                "coupling": "contradiction",
                "strength_band": "strong"
            })

        if 'The US economy entered a recession during the 2022 to 2023 disinflation' in sentence and 'No US recession occurred during the 2022 to 2023 disinflation' in sentence:
            relations.append({
                "source": 13,
                "target": 14,
                "sense": "Alternative",
                "coupling": "exclusive",
                "strength_band": "strong"
            })

    return json.dumps(relations)

response = "The analytical fork in any inflation diagnosis lies in the joint behaviour of prices and quantities. Supply shocks move prices and output in opposite directions, whereas demand shocks move prices and output in the same direction. Sign restrictions of that kind, imposed on structural vector autoregressions or read directly off sectoral price-quantity pairs, remain the workhorse identification device in applied macroeconomics. The magnitude of the episode under dispute is not itself contested. US consumer price index inflation peaked at 9.1 percent in June 2022; in other words, headline US consumer price inflation in June 2022 reached a four-decade high. A figure of that size is compatible with either diagnosis, which is precisely why the identification problem must be solved with disaggregated data rather than with aggregate readings. Narrative accounts assemble candidate impulses on both sides of the market. The American Rescue Plan Act of March 2021 authorized about 1.9 trillion dollars in fiscal support, and transfers of that pandemic-era kind pushed household demand for goods above its pre-pandemic trend. Two conditions are at issue for that period, and at least one of them held, perhaps both: goods demand by households running above its pre-pandemic trend, or container shipping capacity constrained below pre-pandemic throughput levels. The fiscal authorization of March 2021 came first; only afterwards did energy prices rise sharply following Russia's invasion of Ukraine in February 2022. Formal bottleneck measurement has an institutional home of its own: the Global Supply Chain Pressure Index is compiled and published by the Bank of England. What disciplines such competing narratives is quantitative attribution rather than rhetorical plausibility, and the pandemic-era episode has been examined in exactly those terms. That supply-driven factors accounted for the majority of the initial 2021 inflation surge is confirmed by the work of Adam Shapiro of the San Francisco Fed, who decomposed personal consumption expenditures inflation into supply-driven and demand-driven components. Labor market tightness accounted for the majority of the inflation surge in 2021, an accounting that cannot be squared with the attribution just reported; the two cannot both be true, and the measured decomposition is what breaks the tie. The dispute is ultimately settled by the behaviour of real activity as inflation recedes, since genuine demand-driven overheating cannot be unwound without a sacrifice in output and employment, whereas the dissipation of bottlenecks imposes no such cost. Either the US economy entered a recession during the 2022 to 2023 disinflation, or no US recession occurred during the 2022 to 2023 disinflation: one of those two descriptions must hold of the period, and they cannot hold together. Whichever is the case carries the verdict, because disinflation achieved alongside continued expansion of output indicates that binding constraints on supply were relaxing, while disinflation purchased through contraction in activity would indicate that excess aggregate demand had been the operative force. That is why macroeconomists treat the joint path of prices and quantities, both at the onset of an inflation and through its retreat, as the decisive body of evidence."
atoms = {"1": "Supply shocks move prices and output in opposite directions.", "2": "Demand shocks move prices and output in the same direction.", "3": "US consumer price index inflation peaked at 9.1 percent in June 2022.", "4": "Headline US consumer price inflation in June 2022 reached a four-decade high.", "5": "The American Rescue Plan Act of March 2021 authorized about 1.9 trillion dollars in fiscal support.", "6": "Pandemic-era fiscal transfers pushed household demand for goods above its pre-pandemic trend.", "7": "Container shipping capacity was constrained below pre-pandemic throughput levels.", "8": "Energy prices rose sharply after Russia's invasion of Ukraine in February 2022.", "9": "The Global Supply Chain Pressure Index is compiled and published by the Bank of England.", "10": "Adam Shapiro of the San Francisco Fed decomposed personal consumption expenditures inflation into supply-driven and demand-driven components.", "11": "Supply-driven factors accounted for the majority of the initial 2021 inflation surge.", "12": "Labor market tightness accounted for the majority of the inflation surge in 2021.", "13": "The US economy entered a recession during the 2022 to 2023 disinflation.", "14": "No US recession occurred during the 2022 to 2023 disinflation."}

print(recover_relations(response, atoms))
